package net.civeira.phylax.feature.observe.observedslo.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RouteVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property route of observed slo ")
  void test_route_v_o_builder() {
    Assertions.assertFalse(RouteVO.nullValue().getRoute().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(RouteVO.tryFrom(null).getRoute().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", RouteVO.from("one").getRoute().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> RouteVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", RouteVO.from("one").toString());
  }
}
